// Each scenario is one CommonJS program of the tree (basic.cjs, lifo.cjs, errors.cjs, registering.cjs, rejecting.cjs, requiring.cjs, ports.cjs), run
// in a fresh Node process; the test runs the same text in a fresh fast-path loader.
const fs = require("fs"), path = require("path"), { spawnSync } = require("child_process");
const ROOT = "/workspace/r", tree = { files: {} };
(function walk(directory) {
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) walk(file); else tree.files[ROOT + file.slice("/fx".length)] = fs.readFileSync(file, "utf8");
  }
})("/fx");
for (const [file, text] of Object.entries(tree.files)) { fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, text); }
const results = {};
for (const scenario of ["basic", "lifo", "errors", "registering", "rejecting", "requiring", "ports"]) {
  const run = spawnSync(process.execPath, ["-e", `require(${JSON.stringify(`${ROOT}/${scenario}.cjs`)}).then(out => process.stdout.write(JSON.stringify(out)))`], { cwd: ROOT, encoding: "utf8" });
  if (run.status !== 0 || run.stdout === "") { process.stderr.write(`${scenario}: ${run.stderr}`); process.exit(1); }
  results[scenario] = JSON.parse(run.stdout);
}
process.stdout.write(JSON.stringify({ tree, results }, null, 1));

